154	              style={{
155	                borderColor: "var(--border)",
156	                fontSize: "var(--t-sm)",
157	                padding: "11px 18px",
158	                minHeight: 44,
159	              }}
160	            >
161	              ← 인증 허브
162	            </Link>
163	          </div>
164	        </header>
165	
166	        {/* 4 페이즈 밴드 */}
167	        <div className="flex flex-col" style={{ gap: "var(--s-8)" }}>
168	          {adaptedPhases.map((p) => (
