173	              activeId={openId ?? undefined}
174	              onOpen={openStation}
175	              registerRef={(el) => {
176	                if (el) {
177	                  el.dataset.phase = p.id;
178	                  bandRefs.current.set(p.id, el);
179	                } else {
180	                  bandRefs.current.delete(p.id);
181	                }
182	              }}
183	            />
184	          ))}
185	        </div>
186	
187	        <footer
188	          className="text-text-subtle"
189	          style={{
190	            fontSize: "var(--t-xs)",
191	            marginTop: "var(--s-12)",
192	            lineHeight: "var(--lh-base)",
