2	import { useState, useCallback } from "react";
3	
4	export type DocStatus = "not_started" | "in_progress" | "done";
5	type ProgressMap = Record<string, DocStatus>;
6	
7	const storageKey = (certId: string) => `cert-progress-${certId}`;
8	
9	function loadProgress(certId: string): ProgressMap {
10	  try {
11	    return JSON.parse(localStorage.getItem(storageKey(certId)) ?? "{}");
12	  } catch {
13	    return {};
14	  }
15	}
16	
17	function saveProgress(certId: string, map: ProgressMap) {
18	  try {
19	    localStorage.setItem(storageKey(certId), JSON.stringify(map));
20	  } catch {
21	    // localStorage quota exceeded or unavailable — ignore, progress just won't persist
22	  }
23	}
24	
25	export function useProgress(certId: "ivdr" | "iso13485") {
26	  const [progress, setProgress] = useState<ProgressMap>(() => loadProgress(certId));
27	
28	  const setStatus = useCallback(
29	    (docId: string, status: DocStatus) => {
30	      setProgress((prev) => {
31	        const next = { ...prev, [docId]: status };
32	        saveProgress(certId, next);
33	        return next;
34	      });
35	    },
36	    [certId],
37	  );
38	
39	  const getStatus = useCallback(
40	    (docId: string): DocStatus => progress[docId] ?? "not_started",
41	    [progress],
42	  );
43	
44	  const countByStatus = useCallback(
45	    (docIds: string[]) => {
46	      let done = 0, inProgress = 0;
47	      for (const id of docIds) {
48	        const s = progress[id] ?? "not_started";
49	        if (s === "done") done++;
50	        else if (s === "in_progress") inProgress++;
51	      }
52	      return { done, inProgress, total: docIds.length };
53	    },
54	    [progress],
55	  );
56	
57	  return { getStatus, setStatus, countByStatus };
58	}
59	
60	export const STATUS_LABEL: Record<DocStatus, string> = {
61	  not_started: "미작성",
62	  in_progress: "작성 중",
63	  done: "완료",
64	};
65	
66	export const STATUS_NEXT: Record<DocStatus, DocStatus> = {
67	  not_started: "in_progress",
68	  in_progress: "done",
69	  done: "not_started",
70	};
71	
72	export const STATUS_COLOR: Record<DocStatus, string> = {
73	  not_started: "var(--text-subtle)",
74	  in_progress: "var(--warning)",
75	  done: "var(--success)",
76	};
